package com.rewind;

import lombok.Value;

/** Snapshot of completion objectives available at the selected historical date. */
@Value
public class CompletionProgress
{
    int completedQuests;
    int availableQuests;
    int completedSkillMilestones;
    int availableSkillMilestones;
    int completedActivities;
    int availableActivities;

    public int getCompleted()
    {
        return completedQuests + completedSkillMilestones + completedActivities;
    }

    public int getAvailable()
    {
        return availableQuests + availableSkillMilestones + availableActivities;
    }

    public int getPercentage()
    {
        int available = getAvailable();
        return available == 0 ? 0 : (int) Math.round(getCompleted() * 100.0 / available);
    }
}

package com.rewind;

import lombok.Getter;
import java.time.LocalDate;
import java.time.ZoneId;
import java.time.format.DateTimeParseException;
import java.util.Collections;
import java.util.Date;
import java.util.HashMap;
import java.util.Locale;
import java.util.Map;
import net.runelite.api.gameval.ItemID;

@Getter
public class EntityDefinition {
    private static final int FIRST_LEGACY_PICKPOCKET_POUCH = 22521;
    private static final int LAST_LEGACY_PICKPOCKET_POUCH = 22538;
    private static final LocalDate THIEVING_RELEASE = LocalDate.of(2002, 4, 30);
    private int id;
    private String name;
    private String releaseDate;
    private String lastUpdated;
    static Map<Integer, EntityDefinition> itemDefinitions;
    static Map<Integer, EntityDefinition> monsterDefinition;
    static Map<Integer, String> itemReleaseOverrides = Collections.emptyMap();
    private static Map<String, LocalDate> earliestMonsterReleaseByName = Collections.emptyMap();

    static void applyNamedItemReleaseOverrides(Map<String, String> namedOverrides) {
        Map<Integer, String> merged = new HashMap<>();
        if (itemReleaseOverrides != null) {
            merged.putAll(itemReleaseOverrides);
        }
        if (namedOverrides != null) {
            for (Map.Entry<String, String> entry : namedOverrides.entrySet()) {
                Integer id = questItemId(entry.getKey());
                if (id != null) {
                    merged.put(id, entry.getValue());
                }
            }
        }
        itemReleaseOverrides = Collections.unmodifiableMap(merged);
    }

    private static Integer questItemId(String constant) {
        switch (constant) {
            case "ARRAVCERTIFICATE_LFT": return ItemID.ARRAVCERTIFICATE_LFT;
            case "ARRAVCERTIFICATE_RHT": return ItemID.ARRAVCERTIFICATE_RHT;
            case "PIRATEMESSAGE": return ItemID.PIRATEMESSAGE;
            case "WITCHES_SHEDKEY": return ItemID.WITCHES_SHEDKEY;
            case "PAPYRUS": return ItemID.PAPYRUS;
            case "MOSOL_WAMPUM_BELT": return ItemID.MOSOL_WAMPUM_BELT;
            case "PALADINBADGE2": return ItemID.PALADINBADGE2;
            case "SLAVE_BOOTS": return ItemID.SLAVE_BOOTS;
            case "AIR_TALISMAN": return ItemID.AIR_TALISMAN;
            case "RESEARCH_PACKAGE": return ItemID.RESEARCH_PACKAGE;
            case "RESEARCH_NOTES": return ItemID.RESEARCH_NOTES;
            case "ELEMENTAL_WORKSHOP_SHIELD_BOOK_SLASHED": return ItemID.ELEMENTAL_WORKSHOP_SHIELD_BOOK_SLASHED;
            case "FLAMTAER_HAMMER": return ItemID.FLAMTAER_HAMMER;
            case "TIMBERBEAM": return ItemID.TIMBERBEAM;
            default: return null;
        }
    }

    static void indexMonsterDefinitions() {
        Map<String, LocalDate> indexed = new HashMap<>();
        if (monsterDefinition != null) {
            for (EntityDefinition def : monsterDefinition.values()) {
                if (def == null || def.name == null || def.releaseDate == null) continue;
                try {
                    LocalDate release = LocalDate.parse(def.releaseDate);
                    // Keep the earliest known release even when it is post-backup. This lets
                    // an otherwise unknown/new NPC id inherit a verified modern name date
                    // and remain locked instead of falling through as an ordinary NPC.
                    indexed.merge(normalizeName(def.name), release,
                        (first, second) -> first.isBefore(second) ? first : second);
                } catch (DateTimeParseException ignored) {
                    // Invalid source dates remain locked.
                }
            }
        }
        earliestMonsterReleaseByName = indexed;
    }

    private static String normalizeName(String name) {
        return name.trim().toLowerCase(Locale.ROOT);
    }

    // Unknown IDs and missing/invalid dates remain locked. IDs are never used as a date proxy.
    static boolean isUnlocked(EntityDefinition def, Date selected) {
        return isUnlockedDate(def == null ? null : def.releaseDate, selected);
    }

    private static boolean isUnlockedDate(String releaseDate, Date selected) {
        if (releaseDate == null || selected == null) return false;
        try {
            LocalDate introduced = LocalDate.parse(releaseDate);
            LocalDate date = selected.toInstant().atZone(ZoneId.systemDefault()).toLocalDate();
            return HistoricalCutoff.isSupported(introduced) && !introduced.isAfter(date);
        } catch (DateTimeParseException ex) {
            return false;
        }
    }

    public static boolean isItemUnlocked(int id, Date selected) throws java.text.ParseException {
        if (id >= FIRST_LEGACY_PICKPOCKET_POUCH && id <= LAST_LEGACY_PICKPOCKET_POUCH) {
            LocalDate date = selected.toInstant().atZone(ZoneId.systemDefault()).toLocalDate();
            return !date.isBefore(THIEVING_RELEASE);
        }
        EntityDefinition def = itemDefinitions == null ? null : itemDefinitions.get(id);
        if (def == null) return false;

        String release = def.releaseDate;
        if (itemReleaseOverrides != null) {
            String override = itemReleaseOverrides.get(id);
            if (override != null) {
                try {
                    if (release == null || LocalDate.parse(override).isBefore(LocalDate.parse(release))) {
                        release = override;
                    }
                } catch (DateTimeParseException ignored) {
                    // Invalid override stays ignored.
                }
            }
        }
        return isUnlockedDate(release, selected);
    }

    public static boolean isMonsterUnlocked(int id, Date selected) throws java.text.ParseException {
        return isUnlocked(monsterDefinition == null ? null : monsterDefinition.get(id), selected);
    }

    public static boolean isMonsterUnlocked(int id, String visibleName, Date selected) throws java.text.ParseException {
        EntityDefinition definition = monsterDefinition == null ? null : monsterDefinition.get(id);
        if (isUnlocked(definition, selected)) return true;
        if (visibleName == null || selected == null) return false;
        LocalDate earliest = earliestMonsterReleaseByName.get(normalizeName(visibleName));
        if (earliest != null) {
            LocalDate date = selected.toInstant().atZone(ZoneId.systemDefault()).toLocalDate();
            return HistoricalCutoff.isSupported(earliest) && !earliest.isAfter(date);
        }

        // The source is a monster dataset, so many ordinary non-combat NPCs have no row.
        // Preserve truly unknown names to avoid deleting legitimate legacy bankers/shopkeepers,
        // but a known definition with no verified date is fail-closed.
        return definition == null;
    }
}

package com.rewind;

import java.time.LocalDate;

public final class HistoricalCutoff
{
    public static final LocalDate OSRS_BACKUP = LocalDate.of(2007, 8, 10);

    private HistoricalCutoff() {}

    public static boolean isSupported(LocalDate date)
    {
        return date != null && !date.isAfter(OSRS_BACKUP);
    }
}

package com.rewind;

import net.runelite.api.Skill;

public final class HistoricalPermanentExclusions
{
    private HistoricalPermanentExclusions() {}

    public static boolean isSkillPermanentlyLocked(Skill skill)
    {
        return skill == Skill.SAILING;
    }

    public static boolean isSailingWidget(int packedId)
    {
        int group = packedId >>> 16;
        return packedId == net.runelite.api.gameval.InterfaceID.Stats.SAILING
            || group == net.runelite.api.gameval.InterfaceID.SAILING_MENU
            || group == net.runelite.api.gameval.InterfaceID.SAILING_INTRO_HUD
            || (group >= net.runelite.api.gameval.InterfaceID.SAILING_BT_HUD
                && group <= net.runelite.api.gameval.InterfaceID.SAILING_CUSTOMISATION)
            || group == net.runelite.api.gameval.InterfaceID.SAILING_BOAT_CARGOHOLD
            || group == net.runelite.api.gameval.InterfaceID.SAILING_BOAT_CARGOHOLD_SIDE;
    }

    public static boolean isSailingMenuAction(String option, String target)
    {
        String o = option == null ? "" : option.toLowerCase(java.util.Locale.ROOT);
        String t = target == null ? "" : target.replaceAll("<[^>]*>", "").toLowerCase(java.util.Locale.ROOT);
        return o.contains("sailing") || t.contains("sailing") || t.contains("sailing boat");
    }
}

package com.rewind;

import java.util.List;
import java.util.Locale;

/** Exact spell identities: substrings such as Vengeance must not unlock Vengeance Other. */
public final class HistoricalSpellRestrictions {
    private HistoricalSpellRestrictions() {}

    public static String clean(String text) {
        if (text == null) return "";
        return text.replaceAll("<[^>]*>", "").replace('\u00a0', ' ').trim();
    }

    public static boolean allowed(String target, List<RewindSpell> unlocked) {
        String name = clean(target).split(" -> ", 2)[0].trim();
        // Client spelling variants refer to the same historical spell.
        if (name.equals("Teleport Block")) name = "Tele Block";
        if (name.equals("Enchant Crossbow Bolts")) name = "Enchant Crossbow Bolt";
        for (RewindSpell spell : unlocked) if (spell.getName().equalsIgnoreCase(name)) return true;
        return false;
    }

    public static boolean allowedWidget(int packedId, List<RewindSpell> unlocked) {
        return unlocked.stream().anyMatch(spell -> spell.getPackedID() == packedId);
    }
}

package com.rewind;

import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Prayer;
import net.runelite.api.Quest;
import net.runelite.api.Skill;

import java.util.*;

@Slf4j
public class Release {
    @Getter
    private static List<Release> RELEASES = new ArrayList<>();

    @Getter
    private ReleaseDate date;
    @Getter
    private List<Integer> regions;
    @Getter
    private List<Skill> skills;
    @Getter
    private List<Prayer> prayers;
    @Getter
    private List<Quest> quests;
    @Getter
    private List<RewindSpell> spells;
    @Getter
    private String description;

    public Release(ReleaseDate date, List<Integer> regions, List<Skill> skills, List<Prayer> prayers, List<Quest> quests, List<RewindSpell> spells, String description) {
        this.date = date;
        this.skills = skills;
        this.regions = regions;
        this.prayers = prayers;
        this.quests = quests;
        this.spells = spells;
        this.description = description;
    }

    public static void setReleases(Release[] releases) {
        RELEASES = Arrays.stream(releases)
            .sorted(Comparator.comparing(r -> r.date.getLocalDate()))
            .collect(java.util.stream.Collectors.toList());
        for (Release r : RELEASES) {
            if (r.date == null || !HistoricalCutoff.isSupported(r.date.getLocalDate()))
                throw new IllegalArgumentException("Unsupported historical release");
            for (List<?> values : Arrays.asList(r.skills, r.prayers, r.quests, r.spells))
                if (values != null && values.contains(null))
                    throw new IllegalArgumentException("Unknown enum in release " + r.date);
        }
    }

    public static Release getReleaseByDate(ReleaseDate date) {
        return RELEASES.stream().filter(r -> r.date.getLocalDate().equals(date.getLocalDate()))
            .findFirst().orElseThrow(() -> new IllegalArgumentException("Missing release: " + date));
    }

    public static List<Integer> getRegions(Release release) {
        LinkedHashSet<Integer> regions = new LinkedHashSet<>();

        for (Release r : RELEASES) {
            if (r.date.getLocalDate().isAfter(release.date.getLocalDate())) break;
            if (r.regions != null) regions.addAll(r.getRegions());

        }

        return new ArrayList<>(regions);
    }

    public static List<Skill> getSkills(Release release) {
        List<Skill> skills = new ArrayList<>();

        for(Release r : RELEASES) {
            if (r.date.getLocalDate().isAfter(release.date.getLocalDate())) break;
            if(r.skills != null) skills.addAll(r.getSkills());

        }

        skills.removeIf(HistoricalPermanentExclusions::isSkillPermanentlyLocked);
        return skills;
    }

    public static List<Prayer> getPrayers(Release release) {
        List<Prayer> prayers = new ArrayList<>();

        for(Release r : RELEASES) {
            if (r.date.getLocalDate().isAfter(release.date.getLocalDate())) break;
            if(r.prayers != null) prayers.addAll(r.getPrayers());

        }

        return prayers;
    }

    public static List<Quest> getQuests(Release release) {
        List<Quest> quests = new ArrayList<>();

        for(Release r : RELEASES) {
            if (r.date.getLocalDate().isAfter(release.date.getLocalDate())) break;
            if(r.quests != null) quests.addAll(r.getQuests());

        }

        return quests;
    }

    public static List<RewindSpell> getSpells(Release release) {
        List<RewindSpell> spells = new ArrayList<>();

        for(Release r : RELEASES) {
            if (r.date.getLocalDate().isAfter(release.date.getLocalDate())) break;
            if(r.spells != null) spells.addAll(r.getSpells());

        }

        return spells;
    }
}

package com.rewind;

import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Prayer;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Keeps historically unavailable prayers hidden.
 *
 * Spell filtering is deliberately not performed here. Rewind filters the
 * spellbook's native spell array during the spellbookSort script callback so
 * spell widgets, tooltips and menus remain entirely native.
 */
public class RewindAbilityOverlay extends Overlay
{
    private final Client client;
    private final RewindPlugin plugin;

    @Inject
    RewindAbilityOverlay(Client client, RewindPlugin plugin)
    {
        this.client = client;
        this.plugin = plugin;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (client.getGameState() != GameState.LOGGED_IN || plugin.getCurrentRelease() == null)
        {
            return null;
        }

        if (plugin.isTutorialBypass())
        {
            restoreAllAbilities();
            return null;
        }

        List<Prayer> prayers = Release.getPrayers(plugin.getCurrentRelease());
        for (RewindPrayer prayer : RewindPrayer.values())
        {
            Widget widget = client.getWidget(prayer.getPackedID());
            if (widget != null)
            {
                boolean locked = prayer == RewindPrayer.RIGOUR
                    || !prayers.contains(prayer.getPrayer());
                widget.setHidden(locked);
            }
        }

        int prayerGroup = RewindPrayer.RIGOUR.getPackedID() >>> 16;
        hidePrayerWidgetByName(client.getWidget(prayerGroup, 0), "rigour");
        return null;
    }

    private void hidePrayerWidgetByName(Widget widget, String prayerName)
    {
        if (widget == null) return;
        String needle = prayerName.toLowerCase(java.util.Locale.ROOT);
        boolean match = containsText(widget.getName(), needle) || containsText(widget.getText(), needle);
        String[] actions = widget.getActions();
        if (!match && actions != null)
        {
            for (String action : actions)
            {
                if (containsText(action, needle))
                {
                    match = true;
                    break;
                }
            }
        }

        if (match)
        {
            widget.setHidden(true);
            return;
        }

        hidePrayerWidgetChildren(widget.getStaticChildren(), prayerName);
        hidePrayerWidgetChildren(widget.getDynamicChildren(), prayerName);
        hidePrayerWidgetChildren(widget.getNestedChildren(), prayerName);
    }

    private void hidePrayerWidgetChildren(Widget[] children, String prayerName)
    {
        if (children == null) return;
        for (Widget child : children)
        {
            hidePrayerWidgetByName(child, prayerName);
        }
    }

    private static boolean containsText(String value, String needle)
    {
        if (value == null) return false;
        return value.replaceAll("<[^>]*>", "")
            .toLowerCase(java.util.Locale.ROOT)
            .contains(needle);
    }

    void restoreAllAbilities()
    {
        for (RewindPrayer prayer : RewindPrayer.values())
        {
            Widget widget = client.getWidget(prayer.getPackedID());
            if (widget != null) widget.setHidden(false);
        }
    }
}

package com.rewind;

import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPriority;

import javax.inject.Inject;
import java.awt.*;

/**
 * Short-lived in-game banner for Rewind objectives. It deliberately renders in
 * the game viewport rather than using desktop notifications or chat.
 */
public class RewindCompletionOverlay extends Overlay
{
    private static final long DISPLAY_MS = 5000L;
    private static final int WIDTH = 330;
    private static final int HEIGHT = 86;

    private volatile String objective;
    private volatile String timeline;
    private volatile String progress;
    private volatile long visibleUntil;

    @Inject
    RewindCompletionOverlay()
    {
        setLayer(OverlayLayer.ALWAYS_ON_TOP);
        setPriority(OverlayPriority.HIGHEST);
    }

    void show(String objective, String timeline, int completed, int available)
    {
        this.objective = objective;
        this.timeline = timeline;
        this.progress = available > 0 ? completed + " / " + available + " historical objectives" : "";
        this.visibleUntil = System.currentTimeMillis() + DISPLAY_MS;
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (objective == null || System.currentTimeMillis() >= visibleUntil)
        {
            return null;
        }

        Rectangle clip = graphics.getClipBounds();
        int canvasWidth = clip == null ? 765 : clip.x + clip.width;
        int x = Math.max(0, (canvasWidth - WIDTH) / 2);
        int y = 55;

        // OSRS-style dark framed notification with warm gold trim.
        graphics.setColor(new Color(20, 16, 12, 238));
        graphics.fillRect(x, y, WIDTH, HEIGHT);
        graphics.setColor(new Color(111, 86, 51));
        graphics.drawRect(x, y, WIDTH - 1, HEIGHT - 1);
        graphics.setColor(new Color(201, 165, 92));
        graphics.drawRect(x + 2, y + 2, WIDTH - 5, HEIGHT - 5);

        drawCentered(graphics, x, "REWIND COMPLETION", y + 20,
            FontManager.getRunescapeBoldFont(), new Color(255, 152, 31));
        drawCentered(graphics, x, objective, y + 43,
            FontManager.getRunescapeBoldFont(), Color.WHITE);
        drawCentered(graphics, x, "Historical objective completed", y + 60,
            FontManager.getRunescapeSmallFont(), new Color(255, 205, 110));

        String footer = timeline + (progress.isEmpty() ? "" : "  -  " + progress);
        drawCentered(graphics, x, footer, y + 76,
            FontManager.getRunescapeSmallFont(), new Color(190, 190, 190));

        return new Dimension(WIDTH, HEIGHT);
    }

    private static void drawCentered(Graphics2D graphics, int x, String text, int y, Font font, Color color)
    {
        graphics.setFont(font);
        graphics.setColor(color);
        FontMetrics metrics = graphics.getFontMetrics();
        graphics.drawString(text, x + (WIDTH - metrics.stringWidth(text)) / 2, y);
    }
}

package com.rewind;

import net.runelite.client.config.*;

import java.awt.*;

@ConfigGroup(RewindPlugin.CONFIG_GROUP_KEY)
public interface RewindConfig extends Config
{
	@ConfigSection(
			name = "Set date to travel back to",
			description = "General settings for the plugin",
			position = 0
	)
	String generalSettings = "generalSettings";

	@ConfigSection(
			name = "Environment Looks",
			description = "Settings relating to locked regions look",
			position = 1
	)
	String environmentSettings = "environmentSettings";

	@ConfigSection(
			name = "Map Settings",
			description = "Settings relating to the map overlay",
			position = 2
	)
	String mapSettings = "mapSettings";

	// General Settings

	@ConfigItem(
			keyName = RewindPlugin.CONFIG_RELEASE_DATE_KEY,
			name = "Date",
			description = "Release you are restricted to",
			position = 1,
			section = generalSettings
	)
	default ReleaseDate release()
	{
		return ReleaseDate.JANUARY_2001;
	}

	@ConfigItem(
			keyName = "unlockGrandExchange",
			name = "Unlock Grand Exchange",
			description = "Allow access to the Grand Exchange while keeping items newer than the selected date blocked",
			position = 2,
			section = generalSettings
	)
	default boolean unlockGrandExchange()
	{
		return false;
	}

	@ConfigItem(
			keyName = "unlockHomeTeleport",
			name = "Unlock Home Teleport",
			description = "Allow Home Teleport regardless of the selected historical date",
			position = 3,
			section = generalSettings
	)
	default boolean unlockHomeTeleport()
	{
		return false;
	}

	// Environment Looks

	@ConfigItem(
			keyName = "maskLockedScene",
			name = "Mask locked world",
			description = "Cover historically unavailable world tiles using Locked region color",
			position = 19,
			section = environmentSettings
	)
	default boolean maskLockedScene()
	{
		return true;
	}

	@ConfigItem(
			keyName = "maskLockedMinimap",
			name = "Mask locked minimap",
			description = "Cover historically unavailable minimap tiles using Locked region color",
			position = 20,
			section = environmentSettings
	)
	default boolean maskLockedMinimap()
	{
		return true;
	}


	@ConfigItem(
			keyName = "renderLockedRegions",
			name = "Locked chunk shader",
			hidden = true,
			description = "Adds graphical change to all chunk that are locked",
			position = 21,
			section = environmentSettings
	)
	default boolean renderLockedRegions()
	{
		return true;
	}

	@Alpha
	@ConfigItem(
			keyName = "shaderGrayColor",
			name = "Locked region color",
			description = "Color and opacity of locked regions in the world and minimap; changes apply immediately",
			position = 22,
			section = environmentSettings
	)
	default Color shaderGrayColor()
	{
		return new Color(0, 31, 77, 204);
	}

	@Alpha
	@ConfigItem(
			keyName = "shaderGrayAmount",
			name = "Chunk shader opacity",
			hidden = true,
			description = "The amount of gray scale that is applied to a locked chunk in the shader (alpha only)",
			position = 23,
			section = environmentSettings
	)
	default Color shaderGrayAmount()
	{
		return new Color(0, 0, 0, 204);
	}

	@ConfigItem(
			keyName = "hardBorder",
			name = "Hard chunk border",
			hidden = true,
			description = "True = hard border cutoff, False = chunk border gradient",
			position = 24,
			section = environmentSettings
	)
	default boolean hardBorder()
	{
		return true;
	}

	@ConfigItem(
			keyName = "renderRegionBorders",
			name = "Draw chunk border lines",
			description = "Draw the chunk borders in the environment marked by lines",
			position = 25,
			section = environmentSettings
	)
	default boolean renderRegionBorders()
	{
		return false;
	}

	@ConfigItem(
			keyName = "regionBorderWidth",
			name = "Chunk border width",
			description = "How wide the region border will be",
			position = 26,
			section = environmentSettings
	)
	default int regionBorderWidth()
	{
		return 1;
	}

	@Alpha
	@ConfigItem(
			keyName = "regionBorderColor",
			name = "Chunk border color",
			description = "The color of the chunk borders",
			position = 27,
			section = environmentSettings
	)
	default Color regionBorderColor()
	{
		return new Color(0, 200, 83, 200);
	}

	// Map Settings

	@ConfigItem(
			keyName = "drawMapOverlay",
			name = "Draw chunks on map",
			description = "Draw a color overlay for each locked/unlocked chunk",
			position = 28,
			section = mapSettings
	)
	default boolean drawMapOverlay()
	{
		return true;
	}

	@ConfigItem(
			keyName = "invertMapOverlay",
			name = "Invert map overlay",
			description = "Switches which chunks the map will draw the color overlay for (true = locked, false = unlocked)",
			position = 29,
			section = mapSettings
	)
	default boolean invertMapOverlay()
	{
		return true;
	}

	@Alpha
	@ConfigItem(
			keyName = "mapOverlayColor",
			name = "Map overlay color",
			description = "The color the map overlay will draw the chunks in",
			position = 30,
			section = mapSettings
	)
	default Color mapOverlayColor()
	{
		return new Color(0, 0, 0, 255);
	}

	@Alpha
	@ConfigItem(
			keyName = "unlockableOverlayColor",
			name = "Unlockable overlay color",
			description = "The color the map overlay will draw the unlockable chunks in",
			position = 31,
			section = mapSettings
	)
