        assertTrue(Release.getPrayers(release("2005-09-06")).containsAll(Arrays.asList(Prayer.SMITE, Prayer.REDEMPTION, Prayer.RETRIBUTION)));
        assertFalse(Release.getPrayers(release("2006-08-15")).contains(Prayer.EAGLE_EYE));
